# owner: platform
"""Contact sheet for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student


def _cells_for(student: Student) -> List[str]:
    if not (student.email or "").strip():
        raise ValueError(f"no email for {student.display_name}")
    return [student.display_name, student.section, student.email]


def _join_cells(row: List[str], widths: List[int]) -> str:
    padded = (cell.ljust(width) for cell, width in zip(row, widths))
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Aligned name, section and email rows, sorted by name."""
    ordered = sorted(students, key=lambda item: item.display_name)
    if not ordered:
        raise ValueError("no students to list")
    cells = [_cells_for(item) for item in ordered]
    widths = [max(map(len, column)) for column in zip(*cells)]
    return [_join_cells(row, widths) for row in cells]
